נג. עִקַּר עֲלִיַּת וּשְׁלֵמוּת הַמַּלְכוּת דִּקְדֻשָּׁה הוּא עַל־יְדֵי אֱמֶת, וְכֵן עִקַּר בִּנְיַן וְקִיּוּם הָעוֹלָם הוּא עַל־יְדֵי אֱמֶת (שם הל' עדות, הל' ה, ושם מבואר שדיבור אמת הוא בחינת פי שנים). 
נד. יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה תְּחִלָּה, וּתְחִלַּת הַבְּרִיאָה הוּא עֲדַיִן כֻּלּוֹ אֶחָד, כֻּלּוֹ טוֹב, כֻּלּוֹ קֹדֶשׁ, בְּחִינַת אֱמֶת, כִּי עֲדַיִן לֹא נִשְׁתַּלְשְׁלוּ בְּחִינוֹת הַ"חִשְּׁבוֹנוֹת רַבִּים" שֶׁבִּבְחִינַת אַחַר הַבְּרִיאָה, שֶׁמִּשָּׁם עִקַּר אֲחִיזַת הַסִּטְרָא־אָחֳרָא וְהַשֶּׁקֶר. וְעַל־כֵּן יִשְׂרָאֵל הֵם בְּחִינַת "כֻּלּוֹ זֶרַע אֱמֶת", וּכְתִיב: "שְׁאֵרִית יִשְׂרָאֵל לֹא יַעֲשׂוּ עַוְלָה וְלֹא יְדַבְּרוּ כָּזָב", כִּי אֲחִיזָתָם בְּשָׁרְשָׁם מִבְּחִינַת אֱמֶת, שֶׁהוּא בְּחִינַת תְּחִלַּת עֲלִיַּת הַבְּרִיאָה בְּמַחֲשָׁבָה שֶׁהִיא רַק אֱמֶת. וְיֵשׁ כֹּחַ לְיִשְׂרָאֵל לִכְלֹל גַּם עַתָּה בְּחִינַת אַחַר הַבְּרִיאָה בִּבְחִינַת קֹדֶם הַבְּרִיאָה עַל־יְדֵי הָאֱמֶת שֶׁלָּהֶם, כִּי עַל־יְדֵי אֱמֶת נִכְלָל אַחַר הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה. וְהָעִקָּר כְּשֶׁרַבִּים מִיִּשְׂרָאֵל מִתְחַבְּרִים יַחַד לְדָבָר שֶׁבִּקְדֻשָּׁה שֶׁהוּא בְּחִינַת אֱמֶת, וְאָז נִכְלָל יוֹתֵר בְּחִינַת אַחַר הַבְּרִיאָה, שֶׁהִיא בְּחִינַת רַבִּים, בְּקֹדֶם הַבְּרִיאָה, שֶׁהוּא בְּחִינַת כֻּלּוֹ אֶחָד עַל־יְדֵי שֶׁנִּתְחַבְּרוּ יַחַד בְּאַחְדוּת אֶחָד לְדָבָר שֶׁבִּקְדֻשָּׁה שֶׁהוּא בְּחִינַת אֱמֶת, וְאָז יֵשׁ לָהֶם כֹּחַ בְּיוֹתֵר לְהַכְנִיעַ הַשֶּׁקֶר שֶׁאֲחִיזָתוֹ מִבְּחִינַת רַבִּים, כִּי אֵין הַדִּין נִמְתָּק אֶלָּא בְּשָׁרְשׁוֹ. וְעַל־כֵּן עִקַּר בֵּרוּר הָאֱמֶת מִן הַשֶּׁקֶר הוּא עַל־יְדֵי שְׁנֵי עֵדִים דַּיְקָא. וְעַל־כֵּן כְּשֶׁאֶחָד מִיִּשְׂרָאֵל נוֹפֵל לְשֶׁקֶר, חַס וְשָׁלוֹם, אֲזַי הַפְּגָם גָּדוֹל מְאֹד, וּכְאִלּוּ עוֹקֵר עַצְמוֹ מִשָּׁרְשׁוֹ, מִשֹּׁרֶשׁ נִשְׁמוֹת יִשְׂרָאֵל שֶׁעָלוּ בְּמַחֲשָׁבָה תְּחִלָּה כַּנַּ"ל, וּכְשֶׁשְּׁנַיִם מִיִּשְׂרָאֵל מְעִידִין שֶׁקֶר, חַס וְשָׁלוֹם, אֲזַי הַפְּגָם גָּדוֹל בְּיוֹתֵר, וּכְאִלּוּ נוֹתְנִים אֲחִיזָה לְהַשֶּׁקֶר מֵהַשֹּׁרֶשׁ, חַס וְשָׁלוֹם. וְעַל־כֵּן אֵין שְׁנַיִם חֲשׁוּדִים עַל הַשֶּׁקֶר, מֵאַחַר שֶׁהוּא דָּבָר הַנּוֹגֵעַ בְּיוֹתֵר בְּשֹׁרֶשׁ קְדֻשַּׁת יִשְׂרָאֵל, וְזֶה גַּם־כֵּן ב
